mapper.select:
SELECT pgx_id AS pgxId, gene_symbol AS geneSymbol, variant_name AS variantName, drug_name AS drugName, effect, recommendation, evidence_level AS evidenceLevel, source FROM pgx_mappings WHERE 1=1 AND tenant_id = #{tenantId}
AND (gene_symbol ILIKE '%' || #{search} || '%' OR drug_name ILIKE '%' || #{search} || '%')
ORDER BY gene_symbol, drug_name LIMIT #{limit} OFFSET #{offset}
